  if(it&&it.id&&String(it.id).startsWith("cd-")){const el=document.getElementById(it.id);const f=el&&el.querySelector("[data-flip]");key=f?f.dataset.flip:null;
    if(key){P.lastGi=it.gi;P.lastRound=P.round;flip=!!it.ko}}
